import{_ as t,c as i,o as r,ae as a}from"./chunks/framework.Bw0Gm4PQ.js";const p=JSON.parse('{"title":"RESTORING COMMON SENSE TO FEDERAL OFFICE SPACE MANAGEMENT","description":"","frontmatter":{"title":"RESTORING COMMON SENSE TO FEDERAL OFFICE SPACE MANAGEMENT","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/04/restoring-common-sense-to-federal-office-space-management/","publishDate":"2025-04-15T18:18:53-04:00"},"headers":[],"relativePath":"executive-orders/2025-04-15-restoring-common-sense-to-federal-office-space-management.md","filePath":"executive-orders/2025-04-15-restoring-common-sense-to-federal-office-space-management.md"}'),o={name:"executive-orders/2025-04-15-restoring-common-sense-to-federal-office-space-management.md"};function s(n,e,l,c,d,m){return r(),i("div",null,e[0]||(e[0]=[a('<h1 id="restoring-common-sense-to-federal-office-space-management" tabindex="-1">RESTORING COMMON SENSE TO FEDERAL OFFICE SPACE MANAGEMENT <a class="header-anchor" href="#restoring-common-sense-to-federal-office-space-management" aria-label="Permalink to &quot;RESTORING COMMON SENSE TO FEDERAL OFFICE SPACE MANAGEMENT&quot;">​</a></h1><p>Published: Tuesday, April 15, 2025</p><ul><li>The executive order emphasizes the need for federal agencies to be located where the American people are, given the vast geographical spread across over 3.8 million square miles.</li><li>It addresses previous executive orders signed by Presidents Carter and Clinton, which prioritized central business districts and historic properties, respectively, but ultimately hindered cost-effective locations for federal facilities.</li><li>The order revokes: <ul><li>Executive Order 12072 (Federal Space Management)</li><li>Executive Order 13006 (Locating Federal Facilities on Historic Properties)</li></ul></li><li>The order directs the Administrator of General Services to amend relevant federal regulations to align with this new directive on federal office space management.</li><li>Agencies using space under different authorities are required to adhere to this order, as applicable by law.</li><li>Key provisions include: <ul><li>The order does not limit the authority of executive departments or their heads.</li><li>Implementation is contingent upon applicable law and available funding.</li><li>The order does not grant any legal rights or benefits enforceable by any parties against the United States or its entities.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/04/restoring-common-sense-to-federal-office-space-management/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/04/restoring-common-sense-to-federal-office-space-management/</a></p>',4)]))}const h=t(o,[["render",s]]);export{p as __pageData,h as default};
